package org.mockito.internal.verification.argumentmatching;

import java.util.LinkedList;
import java.util.List;

import org.hamcrest.Matcher;
import org.hamcrest.StringDescription;
import org.mockito.internal.matchers.ContainsExtraTypeInformation;

@SuppressWarnings("unchecked")
public class ArgumentMatchingTool {

    /**
     * Suspiciously not matching arguments are those that don't much, the toString() representation is the same but types are different.
     */
    public Integer[] getSuspiciouslyNotMatchingArgsIndexes(List<Matcher> matcherList, Object[] args) {
        Integer[] emptyResult = new Integer[0];
        if (matcherList.size() != args.length) {
            return emptyResult;
        }

        List<Integer> flaggedIndexes = new LinkedList<Integer>();
        for (int idx = 0; idx < matcherList.size(); idx++) {
            Matcher currentMatcher = matcherList.get(idx);
            if (currentMatcher instanceof ContainsExtraTypeInformation) {
                ContainsExtraTypeInformation typedMatcher = (ContainsExtraTypeInformation) currentMatcher;
                boolean isSuspicious = !safelyMatches(currentMatcher, args[idx])
                        && toStringEquals(currentMatcher, args[idx])
                        && !typedMatcher.typeMatches(args[idx]);
                if (isSuspicious) {
                    flaggedIndexes.add(idx);
                }
            }
        }
        return flaggedIndexes.toArray(new Integer[0]);
    }

    private boolean safelyMatches(Matcher matcher, Object argument) {
        try {
            return matcher.matches(argument);
        } catch (Throwable throwable) {
            return false;
        }
    }

    private boolean toStringEquals(Matcher matcher, Object argument) {
        String matcherDescription = StringDescription.toString(matcher);
        return matcherDescription.equals(argument.toString());
    }
}
